<?php
/** Two real engine sessions, same own policy revision and revoked editor under a held lock. */
if(!str_starts_with(getenv('ISSUERS_TEST_DSN')?:'','mysql:'))exit(2);
function projectPolicyRaceDb(string$p):EssentialTestDb{return new EssentialTestDb(new PDO(getenv('ISSUERS_TEST_DSN'),getenv('ISSUERS_TEST_USER'),getenv('ISSUERS_TEST_PASSWORD')),$p);}
if(($argv[1]??'')==='worker'){require_once dirname(__DIR__).'/issuers_core_support.php';require_once APPPATH.'services/CompanyProjectFileSettings.php';$p=$argv[2]??'';if(!preg_match('/^essential_[a-f0-9]{10}_$/D',$p))exit(2);$input=json_decode(stream_get_contents(STDIN),true,8,JSON_THROW_ON_ERROR);$db=projectPolicyRaceDb($p);$GLOBALS['essentialPrefix']=$p;try{(new CompanyProjectFileSettings($db,$p))->save(41,7,$input['revision'],['allow_contact_to_delete_files'=>'0']);echo'saved';}catch(DomainException$e){if(!in_array($e->getMessage(),['company_project_file_settings_stale','company_project_file_settings_denied'],true))throw$e;echo$e->getMessage();}exit;}
require __DIR__.'/project_file_settings.php';$start=$GLOBALS['essentialChecks'];$observer=projectPolicyRaceDb($p);$blocker=(int)$db->query('SELECT CONNECTION_ID() id')->row()->id;
foreach(['duplicate','revocation']as$mode){$rev=$settings->page(41,7)['revision'];$settings->save(41,7,$rev,['allow_contact_to_delete_files'=>'1']);$revision=$settings->page(41,7)['revision'];$workers=[];$db->trans_begin();$db->query('SELECT id FROM '.$p.'issuers_lock WHERE id=1 FOR UPDATE');try{for($n=0;$n<2;$n++){$pipes=[];$proc=proc_open([PHP_BINARY,__FILE__,'worker',$p],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode(['revision'=>$revision]));fclose($pipes[0]);$workers[]=[$proc,$pipes];}$deadline=microtime(true)+15;do{$waiters=essentialLockWaiters($observer,$blocker);if($waiters>=2)break;usleep(20000);}while(microtime(true)<$deadline);essentialCheck($waiters>=2,'two native policy sessions observed waiting: '.$mode);if($mode==='revocation')$db->query('UPDATE '.$p.'staff SET active=0 WHERE staffid=7');$db->trans_commit();$out=[];foreach($workers as[$proc,$pipes]){$out[]=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);essentialCheck(proc_close($proc)===0&&$error==='','native policy child exits clean: '.$mode);}sort($out);if($mode==='duplicate'){essentialCheck($out===['company_project_file_settings_stale','saved'],'one editor commits, waiting old revision rejected');essentialCheck($settings->page(41,7)['revision']===$revision+1&&!ownProjectPolicy($db,$p,41),'one revision increment and coherent deny');}else{essentialCheck($out===['company_project_file_settings_denied','company_project_file_settings_denied'],'editor revoked during wait denies both writers');$db->query('UPDATE '.$p.'staff SET active=1 WHERE staffid=7');essentialCheck($settings->page(41,7)['revision']===$revision&&ownProjectPolicy($db,$p,41),'revoked concurrent writes have no policy effect');}}finally{if($db->pdo->inTransaction())$db->trans_rollback();foreach($workers as[$proc,$pipes])if(is_resource($proc))proc_terminate($proc);}}
echo 'Project settings native contention: '.($GLOBALS['essentialChecks']-$start).' added / '.$GLOBALS['essentialChecks'].' cumulative checks passed.'.PHP_EOL;
